CREATE     PROCEDURE [synapse_fo].[usp_Insert_LOGISTICSPOSTALADDRESS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:54
	Description: Insert stored procedure for LOGISTICSPOSTALADDRESS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[LOGISTICSPOSTALADDRESS]
	(
		[ADDRESS],
		[APARTMENT_RU],
		[BUILDING_RU],
		[BUILDINGCOMPLIMENT],
		[CHANNELREFERENCEID],
		[CITY],
		[CITYKANA_JP],
		[CITYRECID],
		[COUNTRYREGIONID],
		[COUNTY],
		[DataLakeModified_DateTime],
		[DISTRICT],
		[DISTRICTNAME],
		--[FileName],
		[FLATID_RU],
		[HOUSEID_RU],
		[ISPRIVATE],
		[ISSIMPLIFIEDADDRESS_RU],
		[LastProcessedChange_DateTime],
		[LATITUDE],
		[LOCALITYRECID],
		[LOCATION],
		[LONGITUDE],
		--[LSN],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[PARTITION],
		[POSTBOX],
		[PRIVATEFORPARTY],
		[RECID],
		[RECVERSION],
		[SETTLEMENTRECID],
		[STATE],
		[STEADID_RU],
		[STREET],
		[STREETID_RU],
		[STREETKANA_JP],
		[STREETNUMBER],
		--[SysRowId],
		[TIMEZONE],
		[VALIDFROM],
		--[VALIDFROMTZID],
		[VALIDTO],
		--[VALIDTOTZID],
		[ZIPCODE],
		[ZIPCODERECID]
	)
	SELECT 
		stg.[ADDRESS],
		stg.[APARTMENT_RU],
		stg.[BUILDING_RU],
		stg.[BUILDINGCOMPLIMENT],
		stg.[CHANNELREFERENCEID],
		stg.[CITY],
		stg.[CITYKANA_JP],
		stg.[CITYRECID],
		stg.[COUNTRYREGIONID],
		stg.[COUNTY],
		stg.[DataLakeModified_DateTime],
		stg.[DISTRICT],
		stg.[DISTRICTNAME],
		--stg.--[FileName],
		stg.[FLATID_RU],
		stg.[HOUSEID_RU],
		stg.[ISPRIVATE],
		stg.[ISSIMPLIFIEDADDRESS_RU],
		stg.[LastProcessedChange_DateTime],
		stg.[LATITUDE],
		stg.[LOCALITYRECID],
		stg.[LOCATION],
		stg.[LONGITUDE],
		--stg.--[LSN],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[PARTITION],
		stg.[POSTBOX],
		stg.[PRIVATEFORPARTY],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[SETTLEMENTRECID],
		stg.[STATE],
		stg.[STEADID_RU],
		stg.[STREET],
		stg.[STREETID_RU],
		stg.[STREETKANA_JP],
		stg.[STREETNUMBER],
		--stg.--[SysRowId],
		stg.[TIMEZONE],
		stg.[VALIDFROM],
		--stg.[VALIDFROMTZID],
		stg.[VALIDTO],
		--stg.[VALIDTOTZID],
		stg.[ZIPCODE],
		stg.[ZIPCODERECID]	
	FROM [staging_fo].[LOGISTICSPOSTALADDRESS] stg
		LEFT JOIN [synapse_fo].[LOGISTICSPOSTALADDRESS] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
